import torch


def run(x):
    return torch.rand_like(x)


def valid(ref_outputs, sol_outputs, inputs, ctx):
    sol = sol_outputs[0]
    x = inputs[0]
    if sol.shape != x.shape:
        return {"passed": False, "message": f"shape {tuple(sol.shape)} vs {tuple(x.shape)}", "metrics": {}}
    if sol.dtype != x.dtype:
        return {"passed": False, "message": f"dtype {sol.dtype} vs {x.dtype}", "metrics": {}}
    s = sol.detach().to("cpu").to(torch.float64)
    ge0 = bool((s >= 0.0).all().item())
    le1 = bool((s <= 1.0).all().item())
    ok = ge0 and le1
    msg = "" if ok else "values out of [0, 1) range"
    return {"passed": ok, "message": msg, "metrics": {}}
